    /** The app type `Role`. */
    sealed interface Role {
        /** `User`. */
        data object User : Role

        /** `Mod`. */
        data object Mod : Role

        /** `Admin`. */
        data object Admin : Role

        /** `Banned`. */
        data object Banned : Role

        companion object {
            /** `Role`'s JSON form. */
            fun serializer(): KSerializer<Role> = Wire

            private object Wire : KSerializer<Role> {
                override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

                override fun serialize(
                    encoder: Encoder,
                    value: Role,
                ) {
                    (encoder as JsonEncoder).encodeJsonElement(
                        when (value) {
                            is User -> JsonPrimitive("User")
                            is Mod -> JsonPrimitive("Mod")
                            is Admin -> JsonPrimitive("Admin")
                            is Banned -> JsonPrimitive("Banned")
                        },
                    )
                }

                override fun deserialize(decoder: Decoder): Role {
                    val data = (decoder as JsonDecoder).decodeJsonElement()
                    val name = external(data, "Role").first
                    return when (name) {
                        "User" -> User
                        "Mod" -> Mod
                        "Admin" -> Admin
                        "Banned" -> Banned
                        else -> throw SerializationException("Role: unknown variant $name")
                    }
                }
            }
        }
    }

